 r={**s,'outcome':out,'review_depth':depth,'mathematical_attempt':attempt,'precise_remaining_task':gap,'source_versions':meta[a]['versions'],'source_receipts':receipts,'computation_artifacts':comps,'history_screen':'outputs/history-filtered.txt; no substantive prior lane assignment found in bounded word-boundary ID screen','literature_search':['sources/web-search-0.json','sources/web-search-1.json','sources/web-search-2.json','sources/web-search-3.json','sources/web-search-4.json','sources/literature-0.json','sources/literature-1.json','sources/literature-2.json','sources/citing-0.json','sources/citing-4.json','sources/followup-0.json','sources/followup-4.json'],'registry_screen':'outputs/registry-screen.json','credit':0,'lean_endpoint':None,'limitations':['Bounded literature/citation search does not certify worldwide priority.','All arXiv versions in retrieved submission histories downloaded; publisher coverage is partial.','No acceptance claimed; root adjudication required.']}
